views {
  view backend_spotlight of cloud {
    include *

    // 1. Mute the entire canvas
    style * {
      color muted
      opacity 30%
    }

    // 2. Highlight only cloud.backend and its children
    style cloud.backend, cloud.backend.* {
      color primary
      opacity 100%
    }
  }
}

apiInstance1 = instanceOf cloud.api
    apiInstance2 = instanceOf cloud.api
  }
}

view backend_view of cloud.backend {
  include *              // adds cloud.backend + its direct children and their mutual relationships
  include cloud.backend._ // adds only the direct children that connect to what is already included
}

views {
  view backend-overview of cloud.backend {
    include *
  }

  view detail extends backend-overview {
    title "Backend Detail"
    include api
    include * -> cloud.backend
  }
}

global {
  predicateGroup core-services {
    include cloud.* where kind is service
    exclude * where tag is #deprecated
  }
}

views {
  view core-services-overview {
    title "Core Services"
    global predicate core-services
    // per-view style rule applied on top of the predicate group result
    style * where kind is service { color primary; border dashed }
  }
}

views {
  view core-services-with-consumers {
    title "Core Services and Their Consumers"
    global predicate core-services
    // extra include: pull in any element that has a relationship to these services
    include -> cloud.* where kind is service
  }
}

views {
  dynamic view checkout-flow {
    customer -> frontend -> api {
      technology 'HTTPS'
      navigateTo payment-detail
    }
    parallel {
      api -> payments
      api -> inventory
      api -> notifications
    }
  }
}

model {
  extend cloud.api {
    metadata {
      port '9090'
      region 'us-east-1'
    }
    health = component 'Health Check'
  }
}

deployment view infra {
  title "Infrastructure"
  include prod.**
  style * { color red }   // separate style rule — documented pattern for deployment views
}

model {
  api = service 'API' {
    #critical
    technology 'Node.js'
  }
}

// Theme preference (e.g. dark) belongs in likec4.config.json, not in model files.
views {
}

model {
  cloud = system 'Cloud' {
    frontend = container 'Frontend'
    backend = container 'Backend'

    frontend -> backend 'sends requests'
  }
}

model {
  cloud.backend.api -> cloud.db
}

extend SOURCE -> TARGET {
  TAGS
  PROPERTIES  // only `metadata` and `link` allowed
}

extend frontend -> api {
  metadata { qos 'high' }
}

view backend of cloud.backend {
    include *                   // cloud.backend + direct children + internal relationships
    include -> cloud.backend -> // any relationships between cloud.backend and the rest of the model (both directions)
}

// "of" scopes the view — `*` means the scoped element + direct children
view backend of cloud.backend {
    include *
    include -> cloud.backend ->  // incoming/outgoing relations
    ...
}
